import { registerCapture } from '@projexlight/sdk-evidence';
const evidence = await registerCapture({
  tenant_id, captured_by_persona_id, encounter_id,
  media_blob_id, mime: 'image/jpeg',
  source_hash_sha256: hash, geo: { lat, lng, accuracy_m },
});

import { deriveVariant } from '@projexlight/sdk-evidence';
const variant = await deriveVariant({
  evidence_id, kind: 'pii-redacted',
  derivation_engine: 'hdk-image-editor.v1',
});

import { transferCustody } from '@projexlight/sdk-evidence';
await transferCustody({
  evidence_id, from_persona_id, to_persona_id,
  reason: 'escalated to senior review for SIU flagging',
  witnessed_by_persona_id, // tenant policy required
});

import { exportLegalBundle } from '@projexlight/sdk-evidence';
const exp = await exportLegalBundle({
  tenant_id, requested_by_persona_id,
  scope: { evidence_ids: [...], date_range: { from, to } },
  ttl_hours: 168, // 7 days default
});

